import{_ as r,C as o,o as i,c as l,a6 as a,E as t}from"./chunks/framework.5dd0l9Wo.js";const v=JSON.parse('{"title":"Path Traversal","description":"Canonicalisation order, encoding layers, absolute paths, and every PortSwigger file-path traversal lab.","frontmatter":{"title":"Path Traversal","description":"Canonicalisation order, encoding layers, absolute paths, and every PortSwigger file-path traversal lab."},"headers":[],"relativePath":"path-traversal/index.md","filePath":"path-traversal/index.md"}'),d={name:"path-traversal/index.md"};function c(p,e,h,u,b,f){const s=o("LabGroup"),n=o("TopicComplete");return i(),l("div",null,[e[0]||(e[0]=a(`<h1 id="path-traversal" tabindex="-1">Path Traversal <a class="header-anchor" href="#path-traversal" aria-label="Permalink to &quot;Path Traversal&quot;">​</a></h1><p class="wd-section-lede">A path traversal bug is not &quot;the app lets you type \`../\`&quot;. It is a disagreement between the string the application validates and the path the filesystem resolves. The exploit lives in the gap between those two operations.</p><div class="wd-callout"><p><strong>The model.</strong> The application receives a filename, optionally decodes it, optionally checks a prefix or a blocklist, then hands it to an API such as <code>open()</code>, <code>readFile()</code>, or a template loader. The OS then resolves <code>.</code>, <code>..</code>, symlinks, and absolute paths. If validation happened before decoding, or on a different string than the one finally opened, the check is meaningless.</p></div><h2 id="resolution-happens-after-validation" tabindex="-1">Resolution happens after validation <a class="header-anchor" href="#resolution-happens-after-validation" aria-label="Permalink to &quot;Resolution happens after validation&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>filename=../../etc/passwd</span></span>
<span class="line"><span>   │ URL decode            → ../../etc/passwd</span></span>
<span class="line"><span>   │ prefix check          → does it start with /var/www/images/ ?  (after join)</span></span>
<span class="line"><span>   │ path join             → /var/www/images/../../etc/passwd</span></span>
<span class="line"><span>   │ OS normalization      → /etc/passwd</span></span>
<span class="line"><span>   ▼ open()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>The critical question is always: <strong>which of these stages does the security check see?</strong> A filter on the raw parameter, a filter after one decode, and a filter after path joining are three different filters with three different bypasses.</p><details class="details custom-block"><summary>🔬 Under the Hood: <code>%2e%2e%2f</code> is not <code>../</code> to every layer</summary><p>The request line is percent-decoded by the web framework before the application sees it. If the application then performs its own <code>decodeURIComponent</code> or <code>urllib.parse.unquote</code>, a single sequence can be decoded twice. That is why <code>%252e%252e%252f</code> works against filters that strip <code>../</code> after one decode: the first decode produces <code>%2e%2e%2f</code>, the blocklist sees no <code>../</code>, and the second decode produces <code>../</code> just before the file API call.</p><p>A null byte (<code>%00</code>) exploited the same gap in C-based runtimes before the 2000s: the application validated the whole string including <code>.jpg</code>, while <code>open()</code> stopped at the NUL. Modern runtimes reject embedded NULs, but the lab preserves the historical bug.</p></details><details class="details custom-block"><summary>⚙️ Engine Variations: separators and case</summary><ul><li><strong>Linux/macOS:</strong> only <code>/</code> separates; <code>..</code> is resolved by the kernel; backslash is an ordinary filename character.</li><li><strong>Windows:</strong> both <code>\\</code> and <code>/</code> separate; trailing dots and spaces are stripped by some APIs; <code>..\\</code> is as valid as <code>../</code>.</li><li><strong>Java <code>File</code>:</strong> normalises <code>..</code> but <code>Paths.get</code> and <code>getCanonicalPath</code> differ in whether they touch the filesystem.</li><li><strong>PHP:</strong> <code>realpath()</code> resolves symlinks, <code>file_get_contents()</code> does not; wrappers such as <code>php://filter</code> are a separate attack surface.</li></ul></details><h2 id="basic-traversal" tabindex="-1">Basic traversal <a class="header-anchor" href="#basic-traversal" aria-label="Permalink to &quot;Basic traversal&quot;">​</a></h2><p>The parameter is used directly as a relative path under a fixed upload directory. Climbing out with <code>../</code> reaches any file the process can read.</p>`,10)),t(s,{ids:"path-traversal-lab-simple"}),e[1]||(e[1]=a('<h2 id="filters-and-the-order-of-operations" tabindex="-1">Filters and the order of operations <a class="header-anchor" href="#filters-and-the-order-of-operations" aria-label="Permalink to &quot;Filters and the order of operations&quot;">​</a></h2><p>Each filter below fails for a different structural reason:</p><ul><li><strong>Absolute path bypass:</strong> the code prepends a directory but never rejects a leading <code>/</code>; the OS discards the prefix when the path is absolute.</li><li><strong>Non-recursive stripping:</strong> <code>../</code> is removed once, so <code>....//</code> becomes <code>../</code> after the removal.</li><li><strong>Superfluous decode:</strong> the blocklist runs after the first decode, then a second decode reintroduces traversal.</li><li><strong>Start-of-path validation:</strong> the check requires the path to start with the expected directory, so traversal must be placed after that prefix.</li><li><strong>Extension validation:</strong> the check requires <code>.png</code>, so the payload terminates the string with a null byte before the extension.</li></ul>',3)),t(s,{ids:"path-traversal-lab-absolute-path-bypass, path-traversal-lab-sequences-stripped-non-recursively, path-traversal-lab-superfluous-url-decode, path-traversal-lab-validate-start-of-path, path-traversal-lab-validate-file-extension-null-byte-bypass"}),e[2]||(e[2]=a(`<details class="details custom-block"><summary>🔬 Under the Hood: why <code>....//</code> survives a non-recursive strip</summary><p>A naive sanitiser calls <code>replace(&#39;../&#39;, &#39;&#39;)</code> exactly once.</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input:      ....//</span></span>
<span class="line"><span>after one:  ../</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The replacement consumed the inner <code>../</code> but the surrounding characters reconstitute a new traversal sequence. The same class of bug appears with <code>..././</code>, <code>..%2f</code>, and URL-encoded variants. Any sanitiser that scans once and does not re-scan its own output can be defeated by overlapping patterns.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Do not sanitise paths with string replacement. Resolve the final path with a canonicalisation API, then verify it is still inside the intended base directory using a path-component comparison (not a string prefix, which <code>/var/www/images-evil</code> defeats). Reject absolute paths and NUL bytes before resolution, and never trust a file extension as a security boundary.</p></div>`,2)),t(n,{"topic-id":"path-traversal",label:"Mark path traversal complete"})])}const g=r(d,[["render",c]]);export{v as __pageData,g as default};
